package com.cattlefarm.admin.user;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.LocalDateTime;import java.util.List;
public final class UserDtos{private UserDtos(){}public record DataScope(@NotBlank@Pattern(regexp="ALL|HERD|BARN|SELF_CREATED|SELF_ASSIGNED")String scopeType,String scopeObjectId){}public record Item(String userId,String username,String realName,String phone,String status,List<String>roles,List<DataScope>dataScopes,LocalDateTime lastLoginAt,int version){}public record Create(@NotBlank@Pattern(regexp="[A-Za-z0-9_.-]{3,50}")String username,@NotBlank String realName,String phone,@NotBlank@Size(min=6,max=72)String password,@NotEmpty List<String>roleCodes,List<@Valid DataScope>dataScopes){}public record Update(@NotBlank String realName,String phone,@NotBlank@Pattern(regexp="ENABLED|DISABLED")String status,@NotEmpty List<String>roleCodes,List<@Valid DataScope>dataScopes,@Size(min=6,max=72)String newPassword,@NotNull Integer version){}public record Role(String roleId,String roleCode,String roleName,String status,List<String>permissionCodes,int version){}public record CreateRole(@NotBlank@Pattern(regexp="[A-Z][A-Z0-9_]{2,49}")String roleCode,@NotBlank@Size(max=50)String roleName,@NotEmpty List<String>permissionCodes){}public record UpdateRole(@NotBlank@Size(max=50)String roleName,@NotBlank@Pattern(regexp="ENABLED|DISABLED")String status,@NotEmpty List<String>permissionCodes,@NotNull Integer version){}public record PermissionGroup(String code,String name,List<String>roles){} }
